"""Generate a complete signed-results report after independent audit."""
from pathlib import Path
import sys,numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.run_stvg_joint_event_critic_v1 import read,put
from scripts.run_stvg_referdino_condition_hc128_v1 import D,P

def main():
 result=read(P/'RESULTS_PUBLIC.json');audit=read(P/'ROOT_INDEPENDENT_AUDIT.json');assert audit['status']=='pass';g=result['groups']['HC128'];ff=read(P/'TEACHER_FRAME_DIAGNOSTICS_PUBLIC.json');trace=read(P/'QUERY_LINEAGE_PUBLIC.json');cost=read(P/'COST_BREAKDOWN.json');rows=result['rows']
 def val(x):return f"{x['mean']:+.4f} [{x['CI95'][0]:+.4f}, {x['CI95'][1]:+.4f}]"
 text=['# ReferDINO student-conditioned feedback: HC128','', 'Completed interface probe; this is **not** a full OPD result. All128 random parent predictions sealed before new GT scoring. One frozen ReferDINO checkpoint, identical8 physical frames and original full query. Original E+finalMBR time fixed. No new expert or trained model; only per-video temporary content states updated.','', '## Configuration and data','', 'The existing official HC dev split has historical Source/full-method evaluation exposure. Exclude NH16 engineering parents; uniform parent shuffle seed2026101901, reserve32 before selecting128, one uniformly random query per parent. Reserved32 were neither run nor scored and are excluded from this interface selection; they are not globally never-exposed data. NH001 checks interface only. No success or reference-availability selection.','', 'Intervene before spatial decoder layer0: lock the native winning tracked query’s initial proposal ancestor separately in each frame, replace exactly those initial references with student boxes. Preserve native content/text and899 other references; native six-layer spatial evidence reading/pruning/Hungarian tracking/temporal/mask decoders execute. Native sigmoid reference projection to [1e-5,1-1e-5] is reported. Trace every intervention; another selected native lineage is not called successful injected-query correction.','', 'S1 is40 fixed Adam lr.01 updates, mean8[5L1+2(1-GIoU)], on eight independent256D content states through the existing frozen TA-STVG decoder. From identical S1, separately use old T(S0) versus refreshed T(S1),40 steps each, fresh identical Adam. No sampling/OPD claim, no parameter sweep or best-step selection. Width/height may change through the original decoder bbox head; the E baseline itself is immutable.','', '## Student results','', 'All entries are parent-macro paired differences in percentage points;95% paired bootstrap intervals. The space endpoint includes known actual nodes outside all8 teacher positions, with unknown labels omitted rather than filled with zero. All parents remain in full-v means.','', '| Comparison | Full vIoU pp [95% CI] | Outside8 actual-node sIoU pp [95% CI] |','|---|---:|---:|']
 for pair,st in g['paired'].items():text.append(f"| {pair} | {val(st['v'])} | {val(st['unobserved_actual_s'])} |")
 text+=['','## Teacher quality and provenance','', '| Same known observation support | Actual selected-frame IoU pp [95% CI] |','|---|---:|']
 for k,v in ff['teacher_parent_paired_pp'].items():text.append(f'| {k} | {val(v)} |')
 text+=['','IoU0.5 recovery/damage groups are descriptive postseal analysis, not online gates or identity labels. No independent identity annotation exists; low IoU or large motion is not sufficient to claim identity recovery.','']
 for label,v in ff['descriptive_recovery_damage'].items():text.append(f"- {label}: known{v['known']}, originally below0.5:{v['student_bad']}, recovered≥0.5:{v['bad_recovered_ge05']}; originally≥0.5:{v['student_good']}, damaged<0.5:{v['good_damaged_lt05']}.")
 lineage_summary={}
 for name in ['T0','T1']:
  rr=[x for x in trace['rows']if x['teacher']==name];lineage_summary[name]=dict(slots=8*len(rr),survived_final=sum(sum(x['pruning_survival'][-1])for x in rr),selected_intervened=sum(sum(x['selected_is_intervened'])for x in rr),projected_reference_elements=sum(x['initial_reference_projected_elements']for x in rr));v=lineage_summary[name];text.append(f"- {name}: intervention survives last spatial pruning at{v['survived_final']}/{v['slots']} slots; final chosen track actually contains it at{v['selected_intervened']}/{v['slots']}. Projected reference elements:{v['projected_reference_elements']}.")
 motion=dict(changed_S1_queries=sum(r['motion']['S1_changed_nodes']>0 for r in rows),S1_changed_nodes=sum(r['motion']['S1_changed_nodes']for r in rows),S1_mean_state_L2=float(np.mean([r['motion']['S1_state_L2']for r in rows])),S1_mean_center_shift_Ewh=float(np.mean([r['motion']['S1_center_shift_Ewh_mean']for r in rows])),changed_teacher_queries=sum(r['motion']['T1_minus_T0_box_max_abs']>1e-6 for r in rows))
 text+=['', '## State coverage and tails','',f"Real S1 changes{motion['changed_S1_queries']}/128 queries and{motion['S1_changed_nodes']} actual nodes; mean state L2={motion['S1_mean_state_L2']:.6f}, mean center displacement/E width-height={motion['S1_mean_center_shift_Ewh']:.6f}. T1 versus T0 differs by more than1e-6 in{motion['changed_teacher_queries']}/128 queries. No artificial box perturbations were substituted.",'']
 tails={}
 for arm in ['S1','Old_feedback','Refreshed_feedback']:
  dd=[(100*(r['values'][arm]['v']-r['values']['E_MBR']['v']),r['alias'])for r in rows];tails[arm]=dict(positive=sum(v>1e-12 for v,a in dd),negative=sum(v< -1e-12 for v,a in dd),unchanged=sum(abs(v)<=1e-12 for v,a in dd),loss_below_minus3pp=sum(v< -3 for v,a in dd),worst=sorted(dd)[:5],best=sorted(dd,reverse=True)[:5]);v=tails[arm];text.append(f"- {arm}: positive{v['positive']}, negative{v['negative']}, unchanged{v['unchanged']}; worse than−3pp:{v['loss_below_minus3pp']}. Worst/best5 retained in DECISION_PUBLIC.json and all signed rows.")
 text+=['', '## Cost and verification','', f"Total new GPU allocation including failed/preflight attempts={cost['total_GPU_seconds']:.3f}s. Source128 forwards; main Refer128 native+128 T0+128 T1 query forwards, each8 frames; NH001 engineering repeats counted separately. Student15,360 actual updates, three40-step stages per parent; separate decoder/conditional teacher per-query timing in COST_BREAKDOWN.json. Refresh uses an additional teacher query compared with cached-old uptake; equal student budgets do not imply equal expert computation. Old cache acquisition cost is excluded. No new DINO-T calls or pretrained weight updates.", '', 'Independent audit replays saved pruning/matching/native selection, exact S1 reference source, shared starting states, all saved Adam steps/losses, independent DenseTube full metrics/outside8 denominators and parent bootstrap intervals. It is not a second full GPU inference replication. Production CURRENT/MAIN/PAPER remain unchanged.', '', '## Decision boundary', '', 'The experiment asks whether this specific initial-reference intervention provides reliable corrections and whether refreshed feedback helps actual student uptake. Teacher changes alone do not establish benefit. Alternate selected native queries cannot be attributed to correcting the injected query. A direct-supervision gain is not an OPD gain. No automatic full OPD, parameter sweep or held32 confirmation is triggered.', '']
 P.joinpath('REPORT.md').write_text('\n'.join(text))
 decision=dict(status='interface_probe_completed_not_full_OPD',lineage=lineage_summary,motion=motion,tails=tails,teacher_parent_paired_pp=ff['teacher_parent_paired_pp'],student_paired_pp=g['paired'],resource_decision='keep sealed baseline; no automatic followup; assess trace/teacher/student evidence together',no_production_promotion=True)
 put(P/'DECISION_PUBLIC.json',decision)
 review='''# Scientific and engineering review\n\nThis is a reference-input intervention plus matched feedback-uptake probe. It is not ordinary full OPD or evidence that every OPD requires a changing teacher. Query content, other native references, real spatial layers, pruning, matching, temporal and mask modules remain. Intervened query survival and final selection are disclosed; do not equate selecting another native query with correcting the student's query.\n\nHistorical HC data exposure is disclosed. Uniform parent selection, independent reserve for this scheme, prelocked parameters, fixed physical support, actual S1 and equal old/refreshed student budgets are preserved. All prediction branches sealed before GT. Full parent metrics, outside8 actual metrics, unknowns, severe failures and signed results are retained. No GT gating/selection, new observation position, learned mapper/head or pretrained-weight update.\n\nNative-noop and initial-reference roundtrip checks are engineering controls. Saved lineage/Adam/metric audit confirms implementation; it does not prove the injected interface remains semantically reliable. Teacher-local advantages, transmission through student decoder, and refresh advantage are separate questions. Candidate coincidence measures are descriptive geometry, not identities.\n\nResource costs include new Source/teacher/student work and engineering failures, with cached acquisition and loading semantics disclosed. The first capture failed before model inference because a legacy CPU helper set CUDA_VISIBLE_DEVICES empty; isolate its exact pool conversion. A later hash guard stopped when root added teacher audit instrumentation during capture; preserve already sealed cases and resume the remaining cases with new declared pins. Neither recovery changes scientific configuration or overwrites predictions.\n'''
 P.joinpath('ROUND_REVIEW.md').write_text(review)
 engineering=dict(initial_pre_model_failure='legacy CPU input_pool import disabled CUDA; no Source forward before failure',capture_hash_guard_stop='root added teacher-noop instrumentation during Source capture; guard stopped; immutable cases reused, remaining recaptured once',recoveries_preserved=True,no_scientific_parameter_change=True,engineering=read(D/'ENGINEERING.json'),audit=audit)
 put(P/'ENGINEERING_PUBLIC.json',engineering)
 files=['vg_tta/stvg_referdino_condition_hc128_v1.py','scripts/run_stvg_referdino_condition_hc128_v1.py','scripts/continue_stvg_referdino_condition_hc128_v1.py','scripts/score_stvg_referdino_condition_hc128_v1.py','scripts/audit_stvg_referdino_condition_hc128_v1.py','scripts/audit_stvg_referdino_condition_provenance_hc128_v1.py','scripts/report_stvg_referdino_condition_hc128_v1.py','protocols/stvg_referdino_condition_hc128_v1.md']+[str(f.relative_to(ROOT))for f in sorted(P.iterdir())if f.is_file()and f.name!='ROUND_REVIEW.md']
 put(D/'PUBLIC_FILES_FINAL.json',dict(files=files));print('REPORT READY',flush=True)
if __name__=='__main__':main()
